const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const FINE = matchMedia('(pointer:fine)').matches;
const isLight = () => document.documentElement.getAttribute('data-theme') === 'light';
const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const G = !RM && window.gsap && window.ScrollTrigger;

function makeRenderer(canvas){
  const r = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'high-performance' });
  r.setPixelRatio(Math.min(devicePixelRatio, 2));
  r.toneMapping = THREE.ACESFilmicToneMapping; r.toneMappingExposure = 1.05;
  r.outputColorSpace = THREE.SRGBColorSpace;
  return r;
}
function envFor(r){ const p = new THREE.PMREMGenerator(r); const t = p.fromScene(new RoomEnvironment(r), 0.04).texture; p.dispose(); return t; }
function visibleWhenSeen(el, onChange){ const io = new IntersectionObserver(es => onChange(es[0].isIntersecting), { rootMargin: '120px' }); io.observe(el); }

/* ============ CAPA EM PALCO ============
   Montagem (tempo): o barramento entra, o contorno acende e o B se extruda.
   Rolagem: o B gira, explode em peças, vira planta técnica e cada peça se liga
   por um traço de circuito a uma frente de trabalho da Bratecon. */
function heroB(){
  const wrap = document.getElementById('top'), hero = document.getElementById('heroStage');
  const canvas = document.getElementById('heroGL'), oc = document.getElementById('heroCirc');
  if (!wrap || !hero || !canvas) return;
  const r = makeRenderer(canvas);
  const scene = new THREE.Scene(); scene.environment = envFor(r);
  const cam = new THREE.PerspectiveCamera(32, 1, .1, 100); cam.position.set(0, 0, 9);
  const V2 = p => new THREE.Vector2(p[0], p[1]);

  /* centro comum: todas as peças compartilham a origem do símbolo montado */
  const all = new THREE.ExtrudeGeometry(BSHAPE.map(s => new THREE.Shape(s.o.map(V2))), { depth: .34, bevelEnabled: true, bevelThickness: .035, bevelSize: .022, bevelSegments: 4 });
  all.computeBoundingBox(); const gc = new THREE.Vector3(); all.boundingBox.getCenter(gc); const frontZ = all.boundingBox.max.z - gc.z; all.dispose();

  const solid = new THREE.MeshPhysicalMaterial({ color: 0x1d4b9c, metalness: .72, roughness: .3, clearcoat: 1, clearcoatRoughness: .2, envMapIntensity: .8, transparent: true, opacity: 0 });
  const nodeMat = new THREE.MeshPhysicalMaterial({ color: 0x2a62c9, metalness: .6, roughness: .25, clearcoat: 1, emissive: 0x31eaa9, emissiveIntensity: 0, transparent: true, opacity: 0 });
  const backMat = new THREE.MeshStandardMaterial({ color: 0x0c2036, metalness: .55, roughness: .45, transparent: true, opacity: 0 });
  const edgeMat = new THREE.LineBasicMaterial({ color: 0x8ac8f6, transparent: true, opacity: 0 });

  /* placa de circuito interna, com o padrão de barramento no gradiente circuito */
  const tex = (() => {
    const cv = document.createElement('canvas'); cv.width = 900; cv.height = 1000; const x = cv.getContext('2d');
    x.fillStyle = '#071a30'; x.fillRect(0, 0, 900, 1000);
    const g = x.createLinearGradient(0, 0, 900, 1000); g.addColorStop(0, '#31EAA9'); g.addColorStop(.5, '#1EC7C5'); g.addColorStop(1, '#0A90F0');
    x.strokeStyle = g; x.fillStyle = '#071a30'; x.lineWidth = 5; x.lineJoin = 'round';
    for (let i = 0; i < 22; i++){
      const y = 30 + i * 44, bx = 120 + ((i * 137) % 520), dy = (i % 2 ? 1 : -1) * 22;
      x.beginPath(); x.moveTo(0, y); x.lineTo(bx, y); x.lineTo(bx + 22, y + dy); x.lineTo(900, y + dy); x.stroke();
      x.beginPath(); x.arc(bx, y, 9, 0, 7); x.fill(); x.stroke();
    }
    const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace;
    t.repeat.set(1 / 1.778, .5); t.offset.set(.5, .5); return t;
  })();
  const boardMat = new THREE.MeshStandardMaterial({ color: 0x0a1f38, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: .9, roughness: .5, metalness: .2, transparent: true, opacity: 0 });

  /* peças: deslocamento na explosão (unidades do símbolo, que tem 2 de altura) */
  const EXP = {
    bar:    [-.62, .02,  .55], trace0: [-.2, .14, 1.0], trace1: [-.12, 0, 1.1], trace2: [-.2, -.14, 1.0],
    node0:  [.06, .2, 1.65],   node1:  [.32, 0, 1.8],   node2:  [.06, -.2, 1.65],
    upper:  [.55, .42, .25],   lower:  [.6, -.4, .15],  board:  [0, 0, -.55],   back: [.05, 0, -1.25]
  };
  const assembly = new THREE.Group();
  const pivot = new THREE.Group(); pivot.add(assembly); scene.add(pivot);
  const parts = {};
  BPARTS.forEach(P => {
    const thin = P.name === 'board' ? .03 : P.name === 'back' ? .06 : 0;
    const geo = new THREE.ExtrudeGeometry(P.shapes.map(s => new THREE.Shape(s.map(V2))),
      thin ? { depth: thin, bevelEnabled: false } : { depth: .34, bevelEnabled: true, bevelThickness: .035, bevelSize: .022, bevelSegments: 4, curveSegments: 6 });
    if (thin) geo.translate(-gc.x, -gc.y, P.name === 'board' ? -thin / 2 : -.12);
    else geo.translate(-gc.x, -gc.y, -gc.z);
    geo.computeVertexNormals();
    const mat = P.name === 'board' ? boardMat : P.name === 'back' ? backMat : P.name.startsWith('node') ? nodeMat : solid;
    const mesh = new THREE.Mesh(geo, mat);
    const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo, 38), edgeMat);
    const g = new THREE.Group(); g.add(mesh, edges); assembly.add(g);
    parts[P.name] = { g, c: P.c, z: thin ? (P.name === 'board' ? thin / 2 : -.06) : frontZ, e: EXP[P.name] || [0, 0, 0] };
  });

  const key = new THREE.DirectionalLight(0xfff4e6, 1.5); key.position.set(-4, 5, 6);
  const fill = new THREE.DirectionalLight(0x7aa7ff, .6); fill.position.set(4, -2, 3);
  const rim = new THREE.DirectionalLight(0x8ac8f6, 2.6); rim.position.set(3, 3, -5);
  scene.add(key, fill, rim, new THREE.AmbientLight(0xffffff, .12));

  const COL = {};
  const rgba = (hex, a) => { hex = (hex || '#888').replace('#', ''); if (hex.length === 3) hex = hex.split('').map(c => c + c).join(''); const n = parseInt(hex, 16); return 'rgba(' + (n >> 16 & 255) + ',' + (n >> 8 & 255) + ',' + (n & 255) + ',' + a + ')'; };
  let light = false;
  function theme(){
    light = isLight();
    if (light){ solid.color.set(0xb9cbe9); solid.metalness = .35; solid.roughness = .35; nodeMat.color.set(0x9fb8e3); backMat.color.set(0xd5dfee); r.toneMappingExposure = 1.15; }
    else { solid.color.set(0x1d4b9c); solid.metalness = .72; solid.roughness = .3; nodeMat.color.set(0x2a62c9); backMat.color.set(0x0c2036); r.toneMappingExposure = .95; }
    ['--line-strong', '--circ-a', '--circ-b', '--circ-c', '--sky', '--ground', '--ink', '--sky-light'].forEach(k => { COL[k] = css(k) || '#56789E'; });
    edgeMat.color.set(light ? COL['--ink'] : COL['--sky-light']);
    kick();
  }
  new MutationObserver(theme).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });

  const ox = oc ? oc.getContext('2d') : null;
  const labels = [...hero.querySelectorAll('.hlbl li')].map(li => ({ li, part: li.dataset.part, side: li.closest('.hlbl-r') ? 'r' : 'l', a: [0, 0] }));
  const ph2 = document.getElementById('ph2'), inner = hero.querySelector('.inner');
  const scrub = document.getElementById('scrub'), scrubMk = document.getElementById('scrubMk'), scrubPh = scrub ? [...scrub.querySelectorAll('.scrub-ph span')] : [];
  const tk = document.getElementById('scrubTk'); if (tk && !tk.children.length) for (let i = 0; i < 41; i++) tk.appendChild(document.createElement('i'));

  let W = 0, H = 0, mobile = false, vh = 1, vw = 1;
  function anchors(){
    const hr = hero.getBoundingClientRect();
    labels.forEach(L => { const b = L.li.getBoundingClientRect(); L.a = L.side === 'r' ? [b.left - hr.left - 12, b.top - hr.top + b.height / 2] : [b.right - hr.left + 12, b.top - hr.top + b.height / 2]; });
  }
  function size(){
    W = hero.clientWidth; H = hero.clientHeight; mobile = W < 860;
    r.setSize(W, H, false); cam.aspect = W / H; cam.updateProjectionMatrix();
    if (oc){ const d = Math.min(devicePixelRatio, 2); oc.width = W * d; oc.height = H * d; ox.setTransform(d, 0, 0, d, 0, 0); }
    vh = 2 * Math.tan(THREE.MathUtils.degToRad(cam.fov / 2)) * cam.position.z; vw = vh * cam.aspect;
    anchors();
  }
  size(); addEventListener('resize', () => { size(); kick(); });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { anchors(); kick(); });

  const v3 = new THREE.Vector3();
  const toScreen = v => { v.project(cam); return [(v.x * .5 + .5) * W, (-v.y * .5 + .5) * H]; };
  const projA = (x, y) => toScreen(v3.set(x - gc.x, y - gc.y, frontZ).applyMatrix4(assembly.matrixWorld));
  const projPart = p => toScreen(v3.set(p.c[0] - gc.x, p.c[1] - gc.y, p.z).applyMatrix4(p.g.matrixWorld));
  const clamp01 = x => x < 0 ? 0 : x > 1 ? 1 : x;
  const ease = x => { x = clamp01(x); return 1 - Math.pow(1 - x, 3); };
  const inout = x => { x = clamp01(x); return x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; };
  const lerp = (a, b, t) => a + (b - a) * t;

  /* rotas do barramento de abertura, ligando na barra do B */
  function routes(){
    const tg = BMETA.targets.map(t => projA(BMETA.barX, t.y));
    const N = tg.length, gap = mobile ? 9 : 14, c0 = mobile ? 8 : 14;
    const minY = Math.min(...tg.map(p => p[1])), minX = Math.min(...tg.map(p => p[0]));
    const band = Math.max(mobile ? 92 : 100, minY - 56 - (N - 1) * gap), chan0 = minX - (mobile ? 12 : 30);
    return tg.map((p, i) => {
      const y0 = band + i * gap, xc = chan0 - i * gap, tx = p[0], ty = p[1], c = Math.max(0, Math.min(c0, (ty - y0) / 2 - 1));
      return mk(c > 1 ? [[-8, y0], [xc - c, y0], [xc, y0 + c], [xc, ty - c], [xc + c, ty], [tx, ty]] : [[-8, ty], [tx, ty]], BMETA.targets[i]);
    });
  }
  function mk(pts, t){ let len = 0; const seg = [0]; for (let k = 1; k < pts.length; k++){ len += Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]); seg.push(len); } return { pts, seg, len, t }; }
  const at = (R, d) => { for (let k = 1; k < R.pts.length; k++){ if (d <= R.seg[k]){ const a = R.pts[k - 1], b = R.pts[k], u = (d - R.seg[k - 1]) / ((R.seg[k] - R.seg[k - 1]) || 1); return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u]; } } return R.pts[R.pts.length - 1]; };
  function partial(R, f){ const lim = R.len * f; ox.beginPath(); ox.moveTo(R.pts[0][0], R.pts[0][1]); for (let k = 1; k < R.pts.length; k++){ if (R.seg[k] <= lim) ox.lineTo(R.pts[k][0], R.pts[k][1]); else { const p = at(R, lim); ox.lineTo(p[0], p[1]); break; } } ox.stroke(); }
  /* traço de chamada: horizontal a partir do rótulo e 45° até a peça */
  function leader(L, T){
    const [ax, ay] = L.a, [tx, ty] = T, dy = Math.abs(ty - ay);
    const bx = L.side === 'r' ? tx + dy : tx - dy;
    const ok = L.side === 'r' ? bx < ax : bx > ax;
    return mk(ok ? [[ax, ay], [bx, ay], [tx, ty]] : [[ax, ay], [tx, ty]], null);
  }

  const ptr = { x: 0, y: 0 }, cur = { x: 0, y: 0 };
  if (FINE) hero.addEventListener('pointermove', e => { ptr.x = e.clientX / innerWidth - .5; ptr.y = e.clientY / innerHeight - .5; kick(); });
  const st = { p: 0 };
  let trig = null;
  if (G) trig = ScrollTrigger.create({ trigger: wrap, start: 'top top', end: 'bottom bottom', scrub: true, onUpdate: s => { st.p = s.progress; kick(); } });

  /* régua: clicar ou arrastar leva a rolagem para a etapa */
  if (scrub && trig){
    const go = (cx, smooth) => { const b = scrub.getBoundingClientRect(); const f = clamp01((cx - b.left - 16) / (b.width - 32)); const y = trig.start + f * (trig.end - trig.start);
      if (window.__lenis) window.__lenis.scrollTo(y, { immediate: !smooth, duration: 1.1 }); else scrollTo({ top: y, behavior: smooth ? 'smooth' : 'auto' }); };
    let drag = false;
    scrub.addEventListener('pointerdown', e => { drag = true; scrub.setPointerCapture(e.pointerId); go(e.clientX, true); });
    scrub.addEventListener('pointermove', e => { if (drag) go(e.clientX, false); });
    scrub.addEventListener('pointerup', () => { drag = false; });
    scrub.addEventListener('keydown', e => { const d = e.key === 'ArrowRight' ? .1 : e.key === 'ArrowLeft' ? -.1 : 0; if (!d) return; e.preventDefault(); const y = trig.start + clamp01(st.p + d) * (trig.end - trig.start); if (window.__lenis) window.__lenis.scrollTo(y, { duration: .9 }); else scrollTo({ top: y }); });
  }

  const pulses = BMETA.targets.map((t, i) => ({ u: (i * .37) % 1, speed: t.main ? .3 + i * .03 : .2 + i * .02, flash: 0 }));
  const lp = labels.map((L, i) => ({ u: (i * .23) % 1 }));
  const nodeFlash = [0, 0, 0];
  let on = true, raf = 0, t0 = 0, last = 0;
  function kick(){ if (!raf && on) raf = requestAnimationFrame(frame); }

  function frame(t){
    if (!t0 || window.__btHold) t0 = t; const T = RM ? 99 : (t - t0) / 1000, dt = last ? Math.min(.05, (t - last) / 1000) : 0; last = t;
    cur.x += (ptr.x - cur.x) * .05; cur.y += (ptr.y - cur.y) * .05;
    const p = st.p;
    /* fases da rolagem */
    const fx = inout((p - .06) / .32);          /* gira e explode */
    const fb = inout((p - .36) / .2);           /* sólido vira planta */
    const fl = clamp01((p - .5) / .34);         /* conexões com as frentes */
    const fText = 1 - ease(p / .1);             /* texto da abertura sai */
    /* materialização da abertura */
    const m = RM ? 1 : ease((T - 2.0) / 1.15), live = RM ? 0 : clamp01((T - 3) / 1.5);

    /* posição e escala: da direita (abertura) para o centro (explosão) */
    const s0 = vh * (mobile ? .33 : .74) / 2, s1 = vh * (mobile ? .25 : .41) / 2;
    const x0 = vw * (mobile ? .42 : .37), y0 = vh * (mobile ? .27 : -.07);
    const x1 = mobile ? 0 : vw * .05, y1 = mobile ? -vh * .02 : vh * .03;
    pivot.position.set(lerp(x0, x1, fx), lerp(y0, y1, fx), 0);
    pivot.scale.setScalar(lerp(s0, s1, fx) * (.96 + .04 * m));
    pivot.rotation.z = THREE.MathUtils.degToRad(lerp(-9, -24, fx));
    assembly.rotation.y = Math.sin(t * .00035) * .22 * live * (1 - fx) + cur.x * .5 * (1 - fx * .6) + lerp(0, -.95, fx);
    assembly.rotation.x = cur.y * .3 * (1 - fx * .6) + lerp(0, .42, fx);
    assembly.position.y = Math.sin(t * .0007) * .03 * live * (1 - fx);
    assembly.scale.set(1, 1, .02 + .98 * m);
    for (const k in parts){ const P = parts[k]; P.g.position.set(P.e[0] * fx, P.e[1] * fx, P.e[2] * fx); }

    /* materiais: metal na abertura, planta técnica depois */
    solid.opacity = m * (1 - fb * .93); solid.depthWrite = solid.opacity > .5;
    nodeMat.opacity = m * (1 - fb * .85); nodeMat.emissiveIntensity = .6 * fb;
    backMat.opacity = Math.min(1, fx * 1.5) * (1 - fb * .8);
    boardMat.opacity = Math.min(1, fx * 1.6); boardMat.emissiveIntensity = .55 + .5 * fb;
    edgeMat.opacity = Math.max(fb, fx * .25);
    r.render(scene, cam);

    /* camadas HTML */
    if (inner){ inner.style.opacity = fText; inner.style.transform = 'translateY(' + (-40 * (1 - fText)) + 'px)'; inner.style.pointerEvents = fText < .2 ? 'none' : ''; }
    if (ph2){ const a = ease((p - .44) / .12); ph2.style.opacity = a; ph2.style.transform = 'translateY(' + (16 * (1 - a)) + 'px)'; }
    if (scrub){ scrub.style.opacity = G ? Math.max(.0, ease((p - .02) / .06)) : 0; scrub.style.pointerEvents = p > .03 ? '' : 'none';
      scrubMk.style.transform = 'translateX(' + (p * (scrub.clientWidth - 35)) + 'px)'; scrub.setAttribute('aria-valuenow', Math.round(p * 100));
      const ph = p < .06 ? 0 : p < .36 ? 1 : p < .5 ? 2 : 3; scrubPh.forEach((s, i) => s.classList.toggle('on', i === ph)); }

    drawOverlay(T, dt, p, fl, fx);
    raf = (on && !RM) ? requestAnimationFrame(frame) : 0;
  }

  function drawOverlay(T, dt, p, fl, fx){
    if (!ox) return;
    ox.clearRect(0, 0, W, H);
    ox.lineJoin = 'round'; ox.lineCap = 'round';
    /* 1. barramento de abertura (some quando a rolagem começa) */
    const fade = 1 - clamp01(p / .07);
    if (fade > 0){
      const R = routes();
      const lf = ox.createLinearGradient(0, 0, Math.max(160, W * .22), 0);
      lf.addColorStop(0, rgba(COL['--line-strong'], 0)); lf.addColorStop(1, rgba(COL['--line-strong'], .7 * fade));
      R.forEach((L, i) => {
        const f = RM ? 1 : ease((T - .15 - i * .12) / 1.15); if (f <= 0) return;
        ox.strokeStyle = lf; ox.lineWidth = L.t.main ? 1.7 : 1.2; partial(L, f);
        if (f >= 1){ const e = L.pts[L.pts.length - 1]; ox.beginPath(); ox.arc(e[0], e[1], L.t.main ? 4.5 : 3.2, 0, 7); ox.fillStyle = COL['--ground']; ox.fill();
          ox.lineWidth = 1.6; ox.strokeStyle = rgba(L.t.main ? COL['--circ-a'] : COL['--line-strong'], (.55 + .45 * pulses[i].flash) * fade); ox.stroke(); }
      });
      const oa = RM ? 0 : (T < 2.5 ? 1 : 1 - ease((T - 2.5) / .8)), op = RM ? 1 : ease((T - .95) / 1.35);
      if (oa > 0 && op > 0){
        const O = BSHAPE.map(s => { const pts = s.o.map(q => projA(q[0], q[1])); pts.push(pts[0]); return mk(pts, null); });
        const xs = O.flatMap(s => s.pts.map(q => q[0])), ys = O.flatMap(s => s.pts.map(q => q[1]));
        const g = ox.createLinearGradient(Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys));
        g.addColorStop(0, rgba(COL['--circ-a'], oa * fade)); g.addColorStop(.5, rgba(COL['--circ-b'], oa * fade)); g.addColorStop(1, rgba(COL['--circ-c'], oa * fade));
        ox.save(); ox.strokeStyle = g; ox.lineWidth = 1.8; ox.shadowColor = rgba(COL['--circ-b'], .8 * oa); ox.shadowBlur = 14; O.forEach(s => partial(s, op)); ox.restore();
      }
      BMETA.nodes.forEach((n, k) => {
        const pop = RM ? 0 : clamp01((T - 2.1) / .35) * (1 - clamp01((T - 2.9) / .6)), a = Math.max(pop, nodeFlash[k]) * fade; if (a <= .01) return;
        const q = projA(n[0], n[1]), rr = Math.max(14, BMETA.nodeR * pivot.scale.x * (H / vh) * 1.6);
        const gg = ox.createRadialGradient(q[0], q[1], 0, q[0], q[1], rr * 1.8); gg.addColorStop(0, rgba(COL['--circ-a'], .55 * a)); gg.addColorStop(1, rgba(COL['--circ-a'], 0));
        ox.fillStyle = gg; ox.beginPath(); ox.arc(q[0], q[1], rr * 1.8, 0, 7); ox.fill();
      });
      if (!RM){
        const pa = clamp01((T - 2.8) / .6) * fade;
        R.forEach((L, i) => {
          const P = pulses[i], prev = P.u; P.u = (P.u + dt * P.speed * (900 / Math.max(600, L.len))) % 1;
          if (P.u < prev){ P.flash = 1; if (L.t.main) nodeFlash[L.t.node] = 1; } P.flash = Math.max(0, P.flash - dt * 1.6);
          if (pa <= 0) return;
          const q = at(L, P.u * L.len), col = L.t.main ? (P.u < .5 ? COL['--circ-a'] : COL['--circ-c']) : COL['--sky'];
          const a = pa * Math.max(0, Math.min(1, P.u / .08, (1 - P.u) / .04)) * (L.t.main ? 1 : .7), rr = L.t.main ? 22 : 15;
          const gg = ox.createRadialGradient(q[0], q[1], 0, q[0], q[1], rr); gg.addColorStop(0, rgba(col, .9 * a)); gg.addColorStop(1, rgba(col, 0));
          ox.fillStyle = gg; ox.beginPath(); ox.arc(q[0], q[1], rr, 0, 7); ox.fill(); ox.fillStyle = rgba(col, a); ox.beginPath(); ox.arc(q[0], q[1], L.t.main ? 2.6 : 2, 0, 7); ox.fill();
        });
        for (let k = 0; k < 3; k++) nodeFlash[k] = Math.max(0, nodeFlash[k] - dt * 1.4);
      }
    }
    /* 2. traços de chamada: cada peça liga numa frente de trabalho */
    labels.forEach((L, i) => {
      const n = labels.length, f = RM ? (G ? 1 : 0) : ease((fl - i / n * .55) / .45);
      L.li.style.opacity = f; L.li.classList.toggle('on', f > .98);
      if (f <= 0 || !parts[L.part]) return;
      if (mobile){ const q = projPart(parts[L.part]); ox.beginPath(); ox.arc(q[0], q[1], 4, 0, 7); ox.fillStyle = COL['--ground']; ox.fill(); ox.lineWidth = 1.5; ox.strokeStyle = rgba(COL['--circ-a'], .9 * f); ox.stroke(); return; }
      const R = leader(L, projPart(parts[L.part]));
      ox.strokeStyle = rgba(COL['--line-strong'], .85); ox.lineWidth = 1.1; partial(R, f);
      if (f > .98){
        const e = R.pts[R.pts.length - 1];
        ox.beginPath(); ox.arc(e[0], e[1], 4, 0, 7); ox.fillStyle = COL['--ground']; ox.fill(); ox.lineWidth = 1.5; ox.strokeStyle = rgba(COL['--circ-a'], .9); ox.stroke();
        if (!RM){
          const P = lp[i]; P.u = (P.u + dt * .35 * (500 / Math.max(300, R.len))) % 1;
          const q = at(R, P.u * R.len), col = P.u < .5 ? COL['--circ-a'] : COL['--circ-c'], a = Math.min(1, P.u / .1, (1 - P.u) / .1);
          const gg = ox.createRadialGradient(q[0], q[1], 0, q[0], q[1], 14); gg.addColorStop(0, rgba(col, .85 * a)); gg.addColorStop(1, rgba(col, 0));
          ox.fillStyle = gg; ox.beginPath(); ox.arc(q[0], q[1], 14, 0, 7); ox.fill();
        }
      }
    });
  }

  visibleWhenSeen(hero, vis => { on = vis && !document.hidden; if (on && !raf){ last = 0; raf = requestAnimationFrame(frame); } });
  document.addEventListener('visibilitychange', () => { on = !document.hidden; if (on && !raf){ last = 0; raf = requestAnimationFrame(frame); } });
  if (!G) wrap.classList.add('static');
  hero.classList.add('gl');
  theme();
}

/* ============ PALCO FIXO: base comum das seções 08 e 10 ============
   Mesmo formato da capa: o palco gruda na tela, a rolagem conduz as fases,
   a régua mostra a etapa e os traços de chamada ligam peça e texto. */
const kc = x => x < 0 ? 0 : x > 1 ? 1 : x;
const ke = x => { x = kc(x); return 1 - Math.pow(1 - x, 3); };
const kio = x => { x = kc(x); return x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; };
const kl = (a, b, t) => a + (b - a) * t;
